create or replace function private.process_completed_job_business_rules(p_job_id uuid) returns void language plpgsql security definer set search_path='' as $$ declare v_customer uuid; v_equipment uuid; v_condition text; v_agreement uuid; v_visit uuid; begin select customer_id into v_customer from public.jobs where id=p_job_id and status='completed'; if v_customer is null then return; end if; select e.equipment_id,e.condition into v_equipment,v_condition from public.equipment_service_events e where e.job_id=p_job_id order by e.serviced_at desc limit 1; if lower(coalesce(v_condition,'')) in ('poor','monitor') and v_equipment is not null and not exists(select 1 from public.sales_opportunities o where o.equipment_id=v_equipment and o.stage not in ('won','lost','deferred')) then insert into public.sales_opportunities(customer_id,job_id,equipment_id,source,title,category,stage,reason,next_follow_up_at) values(v_customer,p_job_id,v_equipment,'field_equipment',case when lower(v_condition)='poor' then 'Equipment replacement opportunity' else 'Equipment condition follow-up' end,'equipment','new',concat('Technician recorded equipment condition: ',v_condition),now()+interval '2 days'); end if; select v.id,v.agreement_id into v_visit,v_agreement from public.service_agreement_visits v join public.service_agreements a on a.id=v.agreement_id where v.job_id=p_job_id and v.status in ('due','scheduled') and a.status='active' order by v.scheduled_for nulls last,v.created_at limit 1 for update of v; if v_visit is not null then update public.service_agreement_visits set status='completed',completed_at=now() where id=v_visit; update public.service_agreements set visits_remaining=greatest(0,visits_remaining-1),updated_at=now() where id=v_agreement; end if; end $$; create or replace function public.process_completed_job_business_rules(p_job_id uuid) returns void language sql set search_path='' as $$ select private.process_completed_job_business_rules(p_job_id) $$; revoke all on function public.process_completed_job_business_rules(uuid) from public,anon; grant execute on function public.process_completed_job_business_rules(uuid) to authenticated;